CREATE DATABASE IF NOT EXISTS lumen
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;
USE lumen;

CREATE TABLE IF NOT EXISTS usuarios (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL UNIQUE,
    senha VARCHAR(255) NOT NULL,
    criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS categorias (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(80) NOT NULL UNIQUE,
    descricao VARCHAR(255) DEFAULT NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS conteudos (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    categoria_id INT UNSIGNED NOT NULL,
    titulo VARCHAR(180) NOT NULL,
    descricao TEXT NOT NULL,
    imagem_url VARCHAR(500) DEFAULT NULL,
    ano SMALLINT UNSIGNED DEFAULT NULL,
    classificacao VARCHAR(20) DEFAULT NULL,
    duracao_minutos SMALLINT UNSIGNED DEFAULT NULL,
    destaque TINYINT(1) NOT NULL DEFAULT 0,
    criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_conteudos_categoria
        FOREIGN KEY (categoria_id) REFERENCES categorias(id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    INDEX idx_conteudos_categoria (categoria_id),
    INDEX idx_conteudos_titulo (titulo)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS favoritos (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    usuario_id INT UNSIGNED NOT NULL,
    conteudo_id INT UNSIGNED NOT NULL,
    criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_favoritos_usuario
        FOREIGN KEY (usuario_id) REFERENCES usuarios(id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_favoritos_conteudo
        FOREIGN KEY (conteudo_id) REFERENCES conteudos(id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT uq_usuario_conteudo UNIQUE (usuario_id, conteudo_id),
    INDEX idx_favoritos_conteudo (conteudo_id)
) ENGINE=InnoDB;

